(function(){
  var card=document.querySelector(".write-submit-card");
  if(!card) return "NO_CARD";
  var txt=(card.textContent||"").trim().slice(0,200);
  var btn=Array.from(card.querySelectorAll("[class*=submit],button,a")).find(function(e){return (e.textContent||"").trim().indexOf("确认并发布")>=0});
  if(!btn) return "NO_CONFIRM txt="+txt;
  btn.click();
  return "CONFIRM_CLICKED";
